14		"strings"
15	
16		"github.com/spf13/cobra"
17	)
18	
19	const maxMCPFrameBytes = 4 * 1024 * 1024
20	
21	type mcpFrameMode string
22	
23	const (
24		mcpFrameContentLength mcpFrameMode = "content-length"
25		mcpFrameJSONLine      mcpFrameMode = "json-line"
26	)
27	
28	type mcpMessage struct {
29		JSONRPC string          `json:"jsonrpc"`
30		ID      any             `json:"id,omitempty"`
31		Method  string          `json:"method,omitempty"`
32		Params  json.RawMessage `json:"params,omitempty"`
33		Result  any             `json:"result,omitempty"`
34		Error   *mcpError       `json:"error,omitempty"`
35	}
36	
37	type mcpError struct {
38		Code    int    `json:"code"`
39		Message string `json:"message"`
40	}
41	
42	type mcpToolCallParams struct {
43		Name      string         `json:"name"`
44		Arguments map[string]any `json:"arguments"`
45	}
46	
47	func newMCPCommand(opts Options) *cobra.Command {
48		return &cobra.Command{
49			Use:   "mcp",
50			Short: "Serve local brain tools over MCP stdio",
51			Args:  cobra.NoArgs,
52			RunE: func(cmd *cobra.Command, args []string) error {
53				return runMCP(cmd.Context(), cmd.InOrStdin(), cmd.OutOrStdout(), opts)
54			},
55		}
56	}
57	
58	func runMCP(ctx context.Context, in io.Reader, out io.Writer, opts Options) error {
59		reader := bufio.NewReader(in)
60		debugLog := os.Getenv("ENTIRE_BRAIN_MCP_DEBUG_LOG")
61		mcpDebugLog(debugLog, "start")
62		for {
63			msg, frameMode, err := readMCPMessage(reader)
64			if errors.Is(err, io.EOF) {
65				mcpDebugLog(debugLog, "eof")
66				return nil
67			}
68			if err != nil {
69				mcpDebugLog(debugLog, "read_error: "+err.Error())
70				return err
71			}
72			mcpDebugLog(debugLog, "message: "+msg.Method)
73			if msg.ID == nil {
74				continue
75			}
76			response := handleMCPMessage(ctx, opts, msg)
77			if err := writeMCPMessage(out, response, frameMode); err != nil {
78				mcpDebugLog(debugLog, "write_error: "+err.Error())
79				return err
80			}
81			mcpDebugLog(debugLog, "response: "+msg.Method)
82		}
83	}
84	
85	func mcpDebugLog(path, line string) {
86		if strings.TrimSpace(path) == "" {
87			return
88		}
89		f, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o600)
90		if err != nil {
91			return
92		}
93		defer f.Close()
94		fmt.Fprintln(f, line)
95	}
96	
97	func handleMCPMessage(ctx context.Context, opts Options, msg mcpMessage) mcpMessage {
98		response := mcpMessage{JSONRPC: "2.0", ID: msg.ID}
99		switch msg.Method {
100		case "initialize":
101			protocolVersion := mcpInitializeProtocolVersion(msg.Params)
102			response.Result = map[string]any{
103				"protocolVersion": protocolVersion,
104				"capabilities":    map[string]any{"tools": map[string]any{}},
105				"serverInfo":      map[string]any{"name": "entire-brain", "version": opts.Version},
106			}
107		case "tools/list":
108			response.Result = map[string]any{"tools": mcpToolDefinitions()}
109		case "tools/call":
110			result, err := handleMCPToolCall(ctx, opts, msg.Params)
111			if err != nil {
112				response.Error = &mcpError{Code: -32000, Message: err.Error()}
113			} else {
114				response.Result = result
115			}
116		default:
117			response.Error = &mcpError{Code: -32601, Message: "method not found"}
118		}
119		return response
120	}
121	
122	func mcpInitializeProtocolVersion(raw json.RawMessage) string {
123		const fallback = "2024-11-05"
124		var params struct {
125			ProtocolVersion string `json:"protocolVersion"`
126		}
127		if len(raw) == 0 || json.Unmarshal(raw, &params) != nil || strings.TrimSpace(params.ProtocolVersion) == "" {
128			return fallback
129		}
130		return params.ProtocolVersion
131	}
132	
133	func mcpToolDefinitions() []map[string]any {
134		stringArg := func(name, description string) map[string]any {
135			return map[string]any{"type": "string", "description": description, "title": name}
136		}
137		integerArg := func(name, description string) map[string]any {
138			return map[string]any{"type": "integer", "description": description, "title": name, "minimum": 1}
139		}
140		return []map[string]any{
141			{
142				"name":        "brain_stale",
143				"description": "Report local semantic brain freshness for the current repository.",
144				"inputSchema": map[string]any{"type": "object", "properties": map[string]any{}},
145			},
146			{
147				"name":        "brain_brief",
148				"description": "Build a bounded task packet from local brain context, live state, semantic context, and indexed history.",
149				"inputSchema": map[string]any{"type": "object", "required": []string{"task"}, "properties": map[string]any{"task": stringArg("task", "Task or bug description"), "limit": integerArg("limit", "Maximum records per section")}},
150			},
151			{
152				"name":        "brain_query",
153				"description": "Search local semantic symbols.",
154				"inputSchema": map[string]any{"type": "object", "required": []string{"query"}, "properties": map[string]any{"query": stringArg("query", "Symbol or text query"), "limit": integerArg("limit", "Maximum symbols")}},
155			},
156			{
157				"name":        "brain_context",
158				"description": "Return relation-aware local semantic context.",
159				"inputSchema": map[string]any{"type": "object", "required": []string{"query"}, "properties": map[string]any{"query": stringArg("query", "Symbol or text query"), "limit": integerArg("limit", "Maximum symbols")}},
160			},
161			{
162				"name":        "brain_impact",
163				"description": "Traverse local semantic impact relations.",
164				"inputSchema": map[string]any{"type": "object", "required": []string{"query"}, "properties": map[string]any{"query": stringArg("query", "Symbol or text query"), "limit": integerArg("limit", "Maximum symbols"), "depth": integerArg("depth", "Relation depth")}},
165			},
166			{
167				"name":        "brain_changes",
168				"description": "Map local file changes to semantic symbols.",
169				"inputSchema": map[string]any{"type": "object", "properties": map[string]any{"limit": integerArg("limit", "Maximum symbols")}},
170			},
171			{
172				"name":        "brain_history",
173				"description": "Search indexed Entire session history, decisions, validation notes, tool paths, or architecture facts.",
174				"inputSchema": map[string]any{"type": "object", "required": []string{"query"}, "properties": map[string]any{"query": stringArg("query", "History query"), "kind": stringArg("kind", "history, decisions, sessions, validation, tool-paths, or architecture")}},
175			},
176		}
177	}
