179	func handleMCPToolCall(ctx context.Context, opts Options, raw json.RawMessage) (map[string]any, error) {
180		var params mcpToolCallParams
181		if err := json.Unmarshal(raw, &params); err != nil {
182			return nil, err
183		}
184		var out bytes.Buffer
185		cmd := &cobra.Command{Use: params.Name}
186		cmd.SetOut(&out)
187		cmd.SetErr(io.Discard)
188		limit, err := mcpPositiveInt(params.Arguments, "limit", 20)
189		if err != nil {
190			return nil, err
191		}
192		query := mcpString(params.Arguments, "query")
193		switch params.Name {
194		case "brain_stale":
195			target := "."
196			if opts.Env.RepoRoot != "" {
197				target = opts.Env.RepoRoot
198			}
199			err = runSemanticStale(ctx, cmd, opts, target, true)
200		case "brain_brief":
201			task := mcpString(params.Arguments, "task")
202			if strings.TrimSpace(task) == "" {
203				err = errors.New("task is required")
204			} else {
205				err = runBrainBrief(ctx, cmd, opts, brainBriefOptions{limit: limit, json: true}, task)
206			}
207		case "brain_query":
208			err = requireMCPQuery(query)
209			if err == nil {
210				err = runSemanticQuery(ctx, cmd, opts, semanticQueryOptions{limit: limit, json: true}, query)
211			}
212		case "brain_context":
213			err = requireMCPQuery(query)
214			if err == nil {
215				err = runSemanticContext(ctx, cmd, opts, semanticContextOptions{limit: limit, json: true}, query)
216			}
217		case "brain_impact":
218			err = requireMCPQuery(query)
219			if err == nil {
220				depth, depthErr := mcpPositiveInt(params.Arguments, "depth", 1)
221				if depthErr != nil {
222					err = depthErr
223				} else {
224					err = runSemanticImpact(ctx, cmd, opts, semanticImpactOptions{limit: limit, depth: depth, json: true}, query)
225				}
226			}
227		case "brain_changes":
228			err = runSemanticChanges(ctx, cmd, opts, semanticChangesOptions{limit: limit, json: true})
229		case "brain_history":
230			err = requireMCPQuery(query)
231			if err == nil {
232				kind := strings.TrimSpace(mcpString(params.Arguments, "kind"))
233				if kind == "" {
234					kind = "history"
235				}
236				if !validMCPHistoryKind(kind) {
237					err = fmt.Errorf("kind must be history, decisions, sessions, validation, tool-paths, or architecture")
238				} else {
239					err = runBrainHistoryInspect(ctx, cmd, opts, kind, query, true)
240				}
241			}
242		default:
243			err = fmt.Errorf("unknown tool: %s", params.Name)
244		}
245		if err != nil {
246			return nil, err
247		}
248		return map[string]any{"content": []map[string]any{{"type": "text", "text": out.String()}}}, nil
249	}
250	
251	func validMCPHistoryKind(kind string) bool {
252		switch kind {
253		case "history", "decisions", "sessions", "validation", "tool-paths", "architecture":
254			return true
255		default:
256			return false
257		}
258	}
259	
260	func requireMCPQuery(query string) error {
261		if strings.TrimSpace(query) == "" {
262			return errors.New("query is required")
263		}
264		return nil
265	}
266	
267	func mcpString(args map[string]any, key string) string {
268		if value, ok := args[key].(string); ok {
269			return value
270		}
271		return ""
272	}
273	
274	func mcpPositiveInt(args map[string]any, key string, fallback int) (int, error) {
275		value, ok := args[key]
276		if !ok {
277			return fallback, nil
278		}
279		switch typed := value.(type) {
280		case float64:
281			if typed >= 1 && typed <= float64(math.MaxInt) && math.Trunc(typed) == typed {
282				return int(typed), nil
283			}
284		case int:
285			if typed >= 1 {
286				return typed, nil
287			}
288		}
289		return 0, fmt.Errorf("%s must be an integer greater than zero", key)
290	}
291	
292	func readMCPMessage(reader *bufio.Reader) (mcpMessage, mcpFrameMode, error) {
293		length := -1
294		for {
295			line, err := reader.ReadString('\n')
296			if err != nil {
297				return mcpMessage{}, "", err
298			}
299			line = strings.TrimRight(line, "\r\n")
300			if strings.HasPrefix(strings.TrimSpace(line), "{") {
301				var msg mcpMessage
302				if err := json.Unmarshal([]byte(strings.TrimSpace(line)), &msg); err != nil {
303					return mcpMessage{}, "", err
304				}
305				return msg, mcpFrameJSONLine, nil
306			}
307			if line == "" {
308				break
309			}
310			name, value, ok := strings.Cut(line, ":")
311			if ok && strings.EqualFold(strings.TrimSpace(name), "Content-Length") {
312				parsed, err := strconv.Atoi(strings.TrimSpace(value))
313				if err != nil {
314					return mcpMessage{}, "", err
315				}
316				if parsed < 0 {
317					return mcpMessage{}, "", errors.New("Content-Length must be non-negative")
318				}
319				length = parsed
320			}
321		}
322		if length < 0 {
323			return mcpMessage{}, "", errors.New("missing Content-Length")
324		}
325		if length > maxMCPFrameBytes {
326			return mcpMessage{}, "", fmt.Errorf("Content-Length exceeds maximum frame size of %d bytes", maxMCPFrameBytes)
327		}
328		data := make([]byte, length)
329		if _, err := io.ReadFull(reader, data); err != nil {
330			return mcpMessage{}, "", err
331		}
332		var msg mcpMessage
333		if err := json.Unmarshal(data, &msg); err != nil {
334			return mcpMessage{}, "", err
335		}
336		return msg, mcpFrameContentLength, nil
337	}
338	
339	func writeMCPMessage(out io.Writer, msg mcpMessage, frameMode mcpFrameMode) error {
340		data, err := json.Marshal(msg)
341		if err != nil {
342			return err
343		}
344		if frameMode == mcpFrameJSONLine {
345			_, err = fmt.Fprintf(out, "%s\n", data)
346			return err
347		}
348		_, err = fmt.Fprintf(out, "Content-Length: %d\r\n\r\n%s", len(data), data)
349		return err
350	}
