174	func buildBrainHistoryIndex(outputDir string, now time.Time, progress historyIndexProgress) (historyIndex, *historySourceManifest, error) {
175		sessionsRoot := filepath.Join(outputDir, exportSessionsDirectory)
176		index := historyIndex{GeneratedAt: now}
177		if _, err := os.Stat(sessionsRoot); err != nil {
178			if os.IsNotExist(err) {
179				return index, nil, errors.New("session history missing; run `entire brain export` first")
180			}
181			return index, nil, err
182		}
183		files, err := collectHistorySessionFiles(sessionsRoot, &index.Warnings)
184		if err != nil {
185			return index, nil, err
186		}
187	
188		prevCache := loadHistoryScanCache(outputDir)
189		newCache := historyScanCache{Version: historyScanCacheVersion, Files: make(map[string]historyScanCacheEntry, len(files))}
190	
191		total := len(files)
192		if progress != nil {
193			progress(0, total)
194		}
195		seenDecisions := map[string]struct{}{}
196		for i, file := range files {
197			rel, relErr := filepath.Rel(outputDir, file.Path)
198			if relErr != nil {
199				rel = file.Path
200			}
201			rel = filepath.ToSlash(rel)
202	
203			var records []historyRecord
204			if cached, ok := prevCache.Files[rel]; ok && cached.Size == file.Size && cached.ModUnixNano == file.ModUnixNano {
205				records = cached.Records
206			} else {
207				scanned, scanErr := scanHistoryFile(outputDir, file.Path)
208				if scanErr != nil {
209					index.Warnings = append(index.Warnings, scanErr.Error())
210					if progress != nil {
211						progress(i+1, total)
212					}
213					continue
214				}
215				records = scanned
216			}
217			// Only files that scanned cleanly (or were reused) are cached; a file
218			// that errored is left out so the next refresh retries it.
219			newCache.Files[rel] = historyScanCacheEntry{Size: file.Size, ModUnixNano: file.ModUnixNano, Records: records}
220	
221			for _, record := range records {
222				if record.Kind == "decision" {
223					dedupeKey := normalizeHistorySearchText(record.Summary)
224					if _, ok := seenDecisions[dedupeKey]; ok {
225						continue
226					}
227					seenDecisions[dedupeKey] = struct{}{}
228				}
229				index.Records = append(index.Records, record)
230			}
231			if progress != nil {
232				progress(i+1, total)
233			}
234		}
235		saveHistoryScanCache(outputDir, newCache)
236		sort.Slice(index.Records, func(i, j int) bool {
237			if index.Records[i].Kind != index.Records[j].Kind {
238				return index.Records[i].Kind < index.Records[j].Kind
239			}
240			if index.Records[i].Path != index.Records[j].Path {
241				return index.Records[i].Path < index.Records[j].Path
242			}
243			return index.Records[i].Line < index.Records[j].Line
244		})
245		source := &historySourceManifest{
246			GeneratedAt:         now,
247			IndexPath:           historyIndexPath,
248			SessionsFingerprint: brainSessionsFingerprint(outputDir),
249			Records:             len(index.Records),
250			Warnings:            append([]string(nil), index.Warnings...),
251		}
252		for _, record := range index.Records {
253			switch record.Kind {
254			case "decision":
255				source.Decisions++
256			case "learning":
257				source.Learnings++
258			case "validation":
259				source.Validations++
260			case "tool_call":
261				source.ToolCalls++
262			case "code_fact":
263				source.CodeFacts++
264			}
265		}
266		return index, source, nil
267	}
