269	// loadHistoryScanCache reads the per-file scan cache. It always returns a
270	// usable (non-nil map) value: any read/parse error or a version mismatch
271	// yields an empty cache so the index simply rebuilds from scratch.
272	// The cache stores every indexed record for every session, which at scale is
273	// hundreds of megabytes of JSON. It is gzip-compressed on disk to bound the
274	// footprint (the record text compresses heavily).
275	func loadHistoryScanCache(outputDir string) historyScanCache {
276		empty := historyScanCache{Version: historyScanCacheVersion, Files: map[string]historyScanCacheEntry{}}
277		data, err := os.ReadFile(filepath.Join(outputDir, filepath.FromSlash(historyScanCachePath)))
278		if err != nil {
279			return empty
280		}
281		gz, err := gzip.NewReader(bytes.NewReader(data))
282		if err != nil {
283			return empty
284		}
285		defer gz.Close()
286		var cache historyScanCache
287		if err := json.NewDecoder(gz).Decode(&cache); err != nil {
288			return empty
289		}
290		if cache.Version != historyScanCacheVersion || cache.Files == nil {
291			return empty
292		}
293		return cache
294	}
