296	// saveHistoryScanCache persists the per-file scan cache. Failures are
297	// non-fatal: a missing or unwritable cache only costs a full rebuild next time.
298	func saveHistoryScanCache(outputDir string, cache historyScanCache) {
299		var buf bytes.Buffer
300		gz := gzip.NewWriter(&buf)
301		if err := json.NewEncoder(gz).Encode(cache); err != nil {
302			return
303		}
304		if err := gz.Close(); err != nil {
305			return
306		}
307		_ = writeFileAtomic(filepath.Join(outputDir, filepath.FromSlash(historyScanCachePath)), buf.Bytes(), 0o600)
308	}
