357	func collectHistorySessionFiles(sessionsRoot string, warnings *[]string) ([]historySessionFile, error) {
358		var files []historySessionFile
359		err := filepath.WalkDir(sessionsRoot, func(path string, d fs.DirEntry, err error) error {
360			if err != nil {
361				*warnings = append(*warnings, err.Error())
362				return nil
363			}
364			if d.IsDir() {
365				return nil
366			}
367			ext := filepath.Ext(path)
368			if ext != ".jsonl" && ext != ".json" && ext != ".md" && ext != ".txt" {
369				return nil
370			}
371			info, statErr := d.Info()
372			if statErr != nil {
373				*warnings = append(*warnings, statErr.Error())
374				return nil
375			}
376			files = append(files, historySessionFile{
377				Path:        path,
378				SortTime:    historySessionSortTime(path, info.ModTime()),
379				Size:        info.Size(),
380				ModUnixNano: info.ModTime().UnixNano(),
381			})
382			return nil
383		})
384		if err != nil {
385			return nil, err
386		}
387		sort.Slice(files, func(i, j int) bool {
388			if !files[i].SortTime.Equal(files[j].SortTime) {
389				return files[i].SortTime.After(files[j].SortTime)
390			}
391			return files[i].Path < files[j].Path
392		})
393		return files, nil
394	}
