406	func scanHistoryFile(outputDir, path string) ([]historyRecord, error) {
407		f, err := os.Open(path)
408		if err != nil {
409			return nil, err
410		}
411		defer f.Close()
412		rel, _ := filepath.Rel(outputDir, path)
413		rel = filepath.ToSlash(rel)
414		scanner := bufio.NewScanner(f)
415		scanner.Buffer(make([]byte, 0, 64*1024), historyMaxLineBytes)
416		var records []historyRecord
417		lineNumber := 0
418		allowRawText := filepath.Ext(path) == ".md" || filepath.Ext(path) == ".txt"
419		for scanner.Scan() {
420			lineNumber++
421			text := strings.TrimSpace(scanner.Text())
422			if text == "" {
423				continue
424			}
425			if !historyLineMayContainIndexedContent(text) {
426				continue
427			}
428			for _, fragment := range extractHistoryFragments(text, allowRawText) {
429				fragment.Text = strings.TrimSpace(fragment.Text)
430				if fragment.Text == "" {
431					continue
432				}
433				for _, kind := range classifyHistoryFragment(fragment) {
434					records = append(records, historyRecord{
435						ID:      historyRecordID(rel, lineNumber, kind, fragment.Text),
436						Kind:    kind,
437						Path:    rel,
438						Line:    lineNumber,
439						Summary: truncateString(cleanHistorySummary(fragment.Text), 700),
440						Terms:   historyTerms(fragment.Text),
441					})
442				}
443			}
444		}
445		return records, scanner.Err()
446	}
447	
448	func extractHistoryFragments(line string, allowRawText bool) []historyFragment {
449		var obj map[string]any
450		if err := json.Unmarshal([]byte(line), &obj); err != nil {
451			if !allowRawText {
452				return nil
453			}
454			return []historyFragment{{Text: line, Source: "text"}}
455		}
456		return extractHistoryJSONFragments(obj)
457	}
458	
459	func extractHistoryJSONFragments(obj map[string]any) []historyFragment {
460		recordType := jsonString(obj["type"])
461		payload := jsonMap(obj["payload"])
462		switch recordType {
463		case "session_meta", "turn_context", "permission-mode":
464			return nil
465		case "agent_message":
466			return stringFragment(obj["message"], "assistant_message")
467		case "event_msg":
468			return extractCodexEventFragments(payload)
469		case "response_item":
470			return extractCodexResponseFragments(payload)
471		case "assistant":
472			return extractClaudeMessageFragments(obj, "assistant")
473		case "user":
474			return extractClaudeToolResultFragments(obj)
475		case "progress":
476			return nil
477		default:
478			if message := jsonString(obj["message"]); message != "" {
479				return []historyFragment{{Text: message, Source: "message"}}
480			}
481			return nil
482		}
483	}
484	
485	func extractCodexEventFragments(payload map[string]any) []historyFragment {
486		switch jsonString(payload["type"]) {
487		case "agent_message":
488			return stringFragment(payload["message"], "assistant_message")
489		case "user_message":
490			return nil
491		case "task_complete":
492			return stringFragment(payload["last_agent_message"], "final_answer")
493		case "exec_command_end":
494			command := compactJSONValue(payload["command"])
495			return []historyFragment{{Text: command, Source: "tool_call:exec_command"}}
496		case "patch_apply_end":
497			parts := []string{"apply_patch", jsonString(payload["stdout"]), jsonString(payload["stderr"]), compactJSONValue(payload["changes"])}
498			return []historyFragment{{Text: strings.Join(parts, " "), Source: "tool_call:apply_patch"}}
499		default:
500			return nil
501		}
502	}
503	
504	func extractCodexResponseFragments(payload map[string]any) []historyFragment {
505		switch jsonString(payload["type"]) {
506		case "message":
507			role := jsonString(payload["role"])
508			if role != "assistant" {
509				return nil
510			}
511			return extractContentFragments(payload["content"], role+"_message")
512		case "function_call":
513			name := jsonString(payload["name"])
514			return []historyFragment{{Text: strings.TrimSpace(name + " " + compactJSONValue(payload["arguments"])), Source: historyToolCallSource(name)}}
515		case "custom_tool_call":
516			name := jsonString(payload["name"])
517			return []historyFragment{{Text: strings.TrimSpace(name + " " + compactJSONValue(payload["input"])), Source: historyToolCallSource(name)}}
518		case "function_call_output":
519			return extractToolResultFacts(jsonString(payload["output"]))
520		default:
521			return nil
522		}
523	}
524	
525	func extractClaudeToolResultFragments(obj map[string]any) []historyFragment {
526		message := jsonMap(obj["message"])
527		if len(message) == 0 {
528			return nil
529		}
530		content, ok := message["content"].([]any)
531		if !ok {
532			return nil
533		}
534		var fragments []historyFragment
535		for _, item := range content {
536			block := jsonMap(item)
537			if jsonString(block["type"]) != "tool_result" {
