851	func normalizeHistorySearchText(value string) string {
852		var b strings.Builder
853		runes := []rune(value)
854		lastSpace := true
855		for i, r := range runes {
856			if unicode.IsLetter(r) || unicode.IsDigit(r) {
857				if !lastSpace && historyCamelBoundary(runes, i) {
858					b.WriteByte(' ')
859				}
860				b.WriteRune(unicode.ToLower(r))
861				lastSpace = false
862				continue
863			}
864			if !lastSpace {
865				b.WriteByte(' ')
866				lastSpace = true
867			}
868		}
869		return strings.TrimSpace(b.String())
870	}
