872	func historyCamelBoundary(runes []rune, index int) bool {
873		if index <= 0 || index >= len(runes) {
874			return false
875		}
876		current := runes[index]
877		previous := runes[index-1]
878		if !unicode.IsLetter(current) || !(unicode.IsLetter(previous) || unicode.IsDigit(previous)) || !unicode.IsUpper(current) {
879			return false
880		}
881		if unicode.IsLower(previous) || unicode.IsDigit(previous) {
882			return true
883		}
884		if unicode.IsUpper(previous) && index+1 < len(runes) && unicode.IsLower(runes[index+1]) {
885			return true
886		}
887		return false
888	}
