1162		hasUpper := false
1163		hasLower := false
1164		hasDigit := false
1165		hasInternalUpper := false
1166		for i, r := range candidate {
1167			switch {
1168			case unicode.IsUpper(r):
1169				hasUpper = true
1170				if i > 0 {
1171					hasInternalUpper = true
1172				}
1173			case unicode.IsLower(r):
1174				hasLower = true
1175			case unicode.IsDigit(r):
1176				hasDigit = true
1177			}
1178		}
1179		if hasUpper && !hasLower {
1180			return true
1181		}
1182		if hasInternalUpper && hasLower {
1183			return true
1184		}
1185		return hasDigit && (hasUpper || hasLower)
1186	}
