1215	func loadBrainHistoryIndex(brainDir string, source *historySourceManifest) (historyIndex, error) {
1216		if source == nil || source.IndexPath == "" {
1217			return historyIndex{}, errors.New("history index missing; run `entire brain refresh`")
1218		}
