		}
	}
	if branch == "" {
		branch = distillDefaultBranch
	}
	return repoDir, storage.BrainDir, branch, nil
}

func newRecallCommand(opts Options) *cobra.Command {
	var (
		branch     string
		limit      int
		includeAll bool
		jsonOut    bool
	)
	cmd := &cobra.Command{
