		text := strings.TrimSpace(scanner.Text())
		if text == "" {
			continue
		}
		var record factRecord
		if err := json.Unmarshal([]byte(text), &record); err != nil {
			return nil, fmt.Errorf("parse %s line %d: %w", filepath.Base(path), line, err)
