	cmd.Flags().StringVar(&strategy, "strategy", "keep-both", "Conflict strategy: keep-both, prefer-source, or prefer-target")
	cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit the result summary as JSON")
	return cmd
}

