	}
	if st.Delta < 0.09 || st.Delta > 0.13 {
		t.Errorf("delta = %v, want ~0.1", st.Delta)
	}
	if st.T <= 0 {
		t.Errorf("t should be positive for a positive shift, got %v", st.T)
	}
	if st.P > 0.05 {
		t.Errorf("a consistent ~0.1 shift should be significant, p=%v", st.P)
	}
