package cli

import (
	"slices"
	"strings"
	"testing"
	"time"
)

func TestRenderDistillPromptSubstitutesTaxonomy(t *testing.T) {
	now := time.Date(2026, 6, 4, 12, 0, 0, 0, time.UTC)
	prompt, err := renderDistillPrompt(defaultFactTaxonomy(now))
	if err != nil {
		t.Fatalf("renderDistillPrompt: %v", err)
	}
	if strings.Contains(prompt, distillTaxonomyMarker) {
		t.Fatalf("marker not substituted")
	}
	if !strings.Contains(prompt, "preferences") {
		t.Fatalf("rendered prompt missing taxonomy category")
	}
	if !strings.Contains(prompt, "architecture.boundaries.rationale") {
		t.Fatalf("rendered prompt missing known taxonomy path")
	}
	// The fixed-category instruction from the template must survive rendering.
	if !strings.Contains(prompt, "path<TAB>fact") {
		t.Fatalf("rendered prompt missing output-format contract")
	}
}

func TestRenderDistillPromptStripsFrontmatter(t *testing.T) {
	now := time.Date(2026, 6, 4, 12, 0, 0, 0, time.UTC)
	prompt, err := renderDistillPrompt(defaultFactTaxonomy(now))
	if err != nil {
		t.Fatalf("renderDistillPrompt: %v", err)
	}
	// The agent runners pass the prompt as a positional CLI arg, so a leading
	// "---" (YAML frontmatter) would be parsed as an unknown flag and rejected.
	if strings.HasPrefix(prompt, "-") {
		t.Fatalf("prompt must not start with a dash (frontmatter not stripped): %q", prompt[:40])
	}
	if strings.Contains(prompt, "name: entire-brain-distill") {
		t.Fatalf("frontmatter leaked into prompt")
	}
	if !strings.HasPrefix(prompt, "You are an expert note-taker") {
		t.Fatalf("prompt body missing after frontmatter strip: %q", prompt[:40])
	}
}

func TestStripTemplateFrontmatter(t *testing.T) {
	in := "---\nname: x\ndescription: y\n---\n\nBody starts here.\n"
	if got := stripTemplateFrontmatter(in); got != "Body starts here.\n" {
		t.Fatalf("got %q", got)
	}
	// No frontmatter: unchanged.
	plain := "No frontmatter here.\n"
	if got := stripTemplateFrontmatter(plain); got != plain {
		t.Fatalf("plain content changed: %q", got)
	}
	// Unterminated frontmatter: left as-is rather than eating the whole file.
	open := "---\nname: x\nstill going\n"
	if got := stripTemplateFrontmatter(open); got != open {
		t.Fatalf("unterminated frontmatter changed: %q", got)
	}
}

func TestCapWarnings(t *testing.T) {
	var w []string
	for i := 0; i < 120; i++ {
		w = append(w, "warn")
	}
	capped := capWarnings(w, maxDistillWarnings)
	if len(capped) != maxDistillWarnings+1 {
		t.Fatalf("expected %d entries, got %d", maxDistillWarnings+1, len(capped))
	}
	if !strings.Contains(capped[len(capped)-1], "more warnings") {
		t.Fatalf("missing overflow summary: %q", capped[len(capped)-1])
	}
	// Under the cap: unchanged.
	small := []string{"a", "b"}
	if got := capWarnings(small, maxDistillWarnings); len(got) != 2 {
		t.Fatalf("small list changed: %v", got)
	}
}

func TestFactTaxonomyBlockDeterministic(t *testing.T) {
	now := time.Date(2026, 6, 4, 12, 0, 0, 0, time.UTC)
	a := factTaxonomyBlock(defaultFactTaxonomy(now))
	b := factTaxonomyBlock(defaultFactTaxonomy(now))
	if a != b {
		t.Fatalf("taxonomy block not deterministic")
	}
}

func TestDistilledFactsFromOutput(t *testing.T) {
	now := time.Date(2026, 6, 4, 12, 0, 0, 0, time.UTC)
	taxonomy := defaultFactTaxonomy(now)
	anchor := factAnchor{SessionID: "s1", Commit: "abc123", Transcript: "sessions/main/x.jsonl", Line: 12}

	output := strings.Join([]string{
		"preferences.coding.style\tThe user prefers tabs over spaces.",
		"architecture.boundaries.rationale,project.tooling.stack\tThe MCP adapter is stdio-only to keep the local-only boundary.",
		"this line has no tab and should be ignored",
		"bogus.unknown.category\tShould be dropped: top-level not in taxonomy.",
		"   ", // blank
	}, "\n")

	records, warnings := distilledFactsFromOutput(output, taxonomy, anchor, "main", now)
	if len(records) != 2 {
		t.Fatalf("expected 2 records, got %d (%+v)", len(records), records)
	}

	first := records[0]
	if first.Origin != factOriginDistilled || first.Status != factStatusActive {
		t.Errorf("wrong origin/status: %+v", first)
	}
	if first.Branch != "main" {
		t.Errorf("wrong branch: %q", first.Branch)
	}
	if len(first.Provenance) != 1 || first.Provenance[0].SessionID != "s1" || first.Provenance[0].Line != 12 {
		t.Errorf("provenance anchor not attached: %+v", first.Provenance)
	}
	if first.ID != factRecordID(first.Text, first.Paths) {
		t.Errorf("id not content-derived")
	}

	// The multi-path line must be normalized (sorted, both kept).
	var multi *factRecord
	for i := range records {
		if len(records[i].Paths) == 2 {
			multi = &records[i]
		}
	}
	if multi == nil {
		t.Fatalf("expected a two-path record")
	}
	if multi.Paths[0] != "architecture.boundaries.rationale" || multi.Paths[1] != "project.tooling.stack" {
		t.Errorf("paths not normalized/sorted: %v", multi.Paths)
	}

	// The unknown-category line must have produced a warning and no record.
	if !containsWarning(warnings, "unknown category") {
		t.Errorf("expected unknown-category warning, got %v", warnings)
	}
}

func TestDistilledFactsFromOutputTabSeparatedPaths(t *testing.T) {
	now := time.Date(2026, 6, 5, 12, 0, 0, 0, time.UTC)
	taxonomy := defaultFactTaxonomy(now)
	anchor := factAnchor{SessionID: "s1"}

	// The agent separated two paths with a TAB instead of a comma. The second
	// path must not leak into the fact text; both paths must be recovered.
	output := "architecture.data.flow\tconstraints.invariants.general\tHook-supporting agents stamp their config with cli_version."
	records, _ := distilledFactsFromOutput(output, taxonomy, anchor, "main", now)
	if len(records) != 1 {
		t.Fatalf("expected 1 record, got %d", len(records))
	}
	r := records[0]
	if r.Text != "Hook-supporting agents stamp their config with cli_version." {
		t.Fatalf("path leaked into text: %q", r.Text)
	}
	if len(r.Paths) != 2 || r.Paths[0] != "architecture.data.flow" || r.Paths[1] != "constraints.invariants.general" {
		t.Fatalf("both tab-separated paths should be recovered: %v", r.Paths)
	}
}

func TestSplitFactLine(t *testing.T) {
	cases := []struct {
		line  string
		paths []string
		text  string
	}{
		{"a.b.c\tfact text", []string{"a.b.c"}, "fact text"},
		{"a.b.c,d.e.f\tfact text", []string{"a.b.c", "d.e.f"}, "fact text"},
		{"a.b.c\td.e.f\tfact text", []string{"a.b.c", "d.e.f"}, "fact text"},
		// A fact that itself contains a tab keeps everything after the paths.
		{"a.b.c\tprose with\ta tab", []string{"a.b.c"}, "prose with a tab"},
	}
	for _, tc := range cases {
		paths, text := splitFactLine(tc.line)
		if text != tc.text {
			t.Errorf("line %q: text = %q, want %q", tc.line, text, tc.text)
		}
		if len(paths) != len(tc.paths) {
			t.Errorf("line %q: paths = %v, want %v", tc.line, paths, tc.paths)
			continue
		}
		for i := range paths {
			if paths[i] != tc.paths[i] {
				t.Errorf("line %q: paths = %v, want %v", tc.line, paths, tc.paths)
			}
		}
	}
}

func TestDistilledFactsFromOutputCapsPerChunk(t *testing.T) {
	now := time.Date(2026, 6, 4, 12, 0, 0, 0, time.UTC)
	taxonomy := defaultFactTaxonomy(now)
	var lines []string
	for i := 0; i < factsMaxPerChunk+4; i++ {
		lines = append(lines, "project.tooling.stack\tFact number "+string(rune('a'+i)))
	}
	records, warnings := distilledFactsFromOutput(strings.Join(lines, "\n"), taxonomy, factAnchor{SessionID: "s1"}, "main", now)
	if len(records) != factsMaxPerChunk {
		t.Fatalf("expected cap at %d, got %d", factsMaxPerChunk, len(records))
	}
	if !containsWarning(warnings, "extra lines dropped") {
		t.Errorf("expected cap warning, got %v", warnings)
	}
}

func TestDistillAgentCommandArgs(t *testing.T) {
	codex, err := distillAgentCommandArgs("codex", nil, "PROMPT")
	if err != nil || codex[0] != "codex" || codex[len(codex)-1] != "PROMPT" {
		t.Fatalf("codex args wrong: %v err=%v", codex, err)
	}
	claude, err := distillAgentCommandArgs("claude-code", nil, "PROMPT")
	if err != nil || claude[0] != "claude" || claude[len(claude)-1] != "PROMPT" {
		t.Fatalf("claude args wrong: %v err=%v", claude, err)
	}
	// The empty MCP config must be {"mcpServers":{}} — bare {} is rejected by the
	// current claude CLI ("mcpServers: expected record, received undefined").
	if !slices.Contains(claude, `{"mcpServers":{}}`) {
		t.Fatalf("claude args missing valid empty mcp-config: %v", claude)
	}
	cmd, err := distillAgentCommandArgs("command", []string{"my-agent", "--flag"}, "PROMPT")
	if err != nil || len(cmd) != 2 || cmd[0] != "my-agent" {
		t.Fatalf("command args wrong: %v err=%v", cmd, err)
	}
	if _, err := distillAgentCommandArgs("command", nil, "PROMPT"); err == nil {
		t.Errorf("expected error when --agent command has no command")
	}
	if _, err := distillAgentCommandArgs("none", nil, "PROMPT"); err == nil {
		t.Errorf("expected error for --agent none (distillation is agent-required)")
	}
	if _, err := distillAgentCommandArgs("bogus", nil, "PROMPT"); err == nil {
		t.Errorf("expected error for unsupported agent")
	}
}

func containsWarning(warnings []string, substr string) bool {
	for _, w := range warnings {
		if strings.Contains(w, substr) {
			return true
		}
	}
	return false
}

package cli

import (
	"errors"
	"fmt"
	"sort"
	"strings"
	"time"

	entirebrain "github.com/ashtom/entire-brain"
)

const (
	distillTemplateName    = "templates/entire-brain-distill.md"
	distillTaxonomyMarker  = "${TAXONOMY_BLOCK}"
	distillMaxOutputBytes  = 256 * 1024
	distillFactMaxTextSize = 2000
)

// distillTemplate returns the distillation prompt body shipped with the binary,
// with its YAML frontmatter stripped. The frontmatter is metadata for skill
// installers, not part of the prompt — and crucially the agent runners pass the
// prompt as a positional CLI argument, so a leading "---" would be parsed as an
// unknown flag and rejected. A missing template is a build error, not runtime.
func distillTemplate() (string, error) {
	data, err := entirebrain.Templates.ReadFile(distillTemplateName)
	if err != nil {
		return "", fmt.Errorf("read distill template: %w", err)
	}
	return stripTemplateFrontmatter(string(data)), nil
}

// stripTemplateFrontmatter removes a leading YAML frontmatter block
// ("---\n...\n---\n") and returns the body. Content without frontmatter is
// returned unchanged.
func stripTemplateFrontmatter(content string) string {
	if !strings.HasPrefix(content, "---\n") && !strings.HasPrefix(content, "---\r\n") {
		return content
	}
	lines := strings.Split(content, "\n")
	for i := 1; i < len(lines); i++ {
		if strings.TrimSpace(lines[i]) == "---" {
			return strings.TrimLeft(strings.Join(lines[i+1:], "\n"), "\n")
		}
	}
	return content // no closing delimiter; leave as-is
}

// renderDistillPrompt substitutes the active taxonomy into the template's
// ${TAXONOMY_BLOCK} marker. The rendered prompt is what gets passed to the seed
// agent as its system prompt; the line-numbered transcript chunk is the input.
func renderDistillPrompt(taxonomy factTaxonomy) (string, error) {
	template, err := distillTemplate()
	if err != nil {
		return "", err
	}
	if !strings.Contains(template, distillTaxonomyMarker) {
		return "", fmt.Errorf("distill template missing %s marker", distillTaxonomyMarker)
	}
	return strings.ReplaceAll(template, distillTaxonomyMarker, factTaxonomyBlock(taxonomy)), nil
}

// factTaxonomyBlock renders the taxonomy as the prompt section the agent uses to
// classify facts: the fixed top-level categories and the known three-level
// paths with descriptions. Output is deterministic (sorted) so the rendered
// prompt is stable across runs.
func factTaxonomyBlock(taxonomy factTaxonomy) string {
	var b strings.Builder
	b.WriteString("## Taxonomy\n\n")
	b.WriteString("Top-level categories are fixed. You may invent a new three-level path only under one of these categories:\n\n")

	categories := make([]string, 0, len(taxonomy.Categories))
	for category := range taxonomy.Categories {
		categories = append(categories, category)
	}
	sort.Strings(categories)
	for _, category := range categories {
		fmt.Fprintf(&b, "- `%s` — %s\n", category, taxonomy.Categories[category])
	}

	if len(taxonomy.Paths) > 0 {
		b.WriteString("\nKnown paths (prefer these):\n\n")
		paths := append([]factPathDef(nil), taxonomy.Paths...)
		sort.Slice(paths, func(i, j int) bool { return paths[i].Path < paths[j].Path })
		for _, def := range paths {
			if def.Description != "" {
				fmt.Fprintf(&b, "- `%s` — %s\n", def.Path, def.Description)
			} else {
				fmt.Fprintf(&b, "- `%s`\n", def.Path)
			}
		}
	}
	return b.String()
}

// distillAgentCommandArgs builds the argv that runs the seed agent with the
// rendered distillation prompt. It mirrors seedAgentCommandArgs: the prompt is
// the agent's system prompt and the transcript chunk is supplied on stdin. The
// no-agent mode ("none") has no command — distillation is agent-required.
func distillAgentCommandArgs(agent string, agentCommand []string, prompt string) ([]string, error) {
	switch agent {
	case "command":
		if len(agentCommand) == 0 {
			return nil, errors.New("--agent-command is required when --agent command")
		}
		return append([]string(nil), agentCommand...), nil
	case "codex":
		return []string{"codex", "exec", "--skip-git-repo-check", "--ephemeral", "--ignore-user-config", "--ignore-rules", "--sandbox", "read-only", prompt}, nil
	case "claude-code":
		return []string{"claude", "--print", "--no-session-persistence", "--setting-sources", "user", "--strict-mcp-config", "--mcp-config", "{\"mcpServers\":{}}", "--disable-slash-commands", "--permission-mode", "dontAsk", "--tools", "", "--system-prompt", prompt}, nil
	case "none", "":
		return nil, errors.New("distillation requires an agent; --agent none has nothing to run")
	default:
		return nil, fmt.Errorf("unsupported --agent %q", agent)
	}
}

// distilledFactsFromOutput parses the agent's line-based output for one
// transcript chunk into fact records. Each emitted line is
// `path[,path]<TAB>fact`. Lines are dropped (with a warning) when they have no
// tab, no syntactically valid path, or no path whose top-level category exists
// in the active taxonomy — the taxonomy's top levels are fixed, so a path under
// an unknown category cannot be trusted. Output is capped at factsMaxPerChunk;
// extra lines are dropped with a warning so a runaway agent cannot flood the
// store.
//
// Every produced record cites the supplied anchor as its provenance and is
// stamped origin=distilled, status=active. Ids are content-derived, so the same
// statement from the same chunk is idempotent across reruns.
func distilledFactsFromOutput(output string, taxonomy factTaxonomy, anchor factAnchor, branch string, now time.Time) ([]factRecord, []string) {
	var records []factRecord
	var warnings []string
	capped := false
	for _, raw := range strings.Split(output, "\n") {
		line := strings.TrimRight(raw, "\r")
		if strings.TrimSpace(line) == "" {
			continue
		}
		if !strings.ContainsRune(line, '\t') {
			// Prose / preamble the template forbids; ignore quietly unless it
			// looks like an attempted fact (contains a path-like token).
			if strings.Contains(line, ".") && strings.Contains(line, " ") {
				warnings = append(warnings, "dropped line without tab separator: "+truncateString(strings.TrimSpace(line), 120))
			}
			continue
		}
		rawPaths, text := splitFactLine(line)
		if text == "" {
			continue
		}
		paths := normalizeFactPaths(rawPaths)
		paths = filterFactPathsByTaxonomy(paths, taxonomy, &warnings)
		if len(paths) == 0 {
			warnings = append(warnings, "dropped fact with no valid taxonomy path: "+truncateString(text, 120))
			continue
		}
		if len(records) >= factsMaxPerChunk {
			capped = true
			continue
		}
		text = truncateString(text, distillFactMaxTextSize)
		records = append(records, factRecord{
			ID:         factRecordID(text, paths),
			Paths:      paths,
			Text:       text,
			Branch:     branch,
			Origin:     factOriginDistilled,
			Status:     factStatusActive,
			Provenance: []factAnchor{anchor},
			CreatedAt:  now,
			UpdatedAt:  now,
		})
	}
	if capped {
		warnings = append(warnings, fmt.Sprintf("chunk produced more than %d facts; extra lines dropped", factsMaxPerChunk))
	}
	return records, warnings
}

// splitFactLine separates a distill output line into its path tokens and fact
// text. The template specifies `path[,path]<TAB>fact`, but agents sometimes
// separate multiple paths with tabs instead of commas (`path<TAB>path<TAB>fact`),
// which would otherwise leak a path into the fact text. It therefore consumes
// leading tab-separated fields for as long as each is a path-block (comma-joined
// valid paths, no prose), and treats the remainder as the fact. Prose cannot
// match the strict path pattern (it contains spaces), so a fact is never
// mistaken for a path.
func splitFactLine(line string) ([]string, string) {
	fields := strings.Split(line, "\t")
	var paths []string
	i := 0
	for i < len(fields)-1 { // always leave at least one field for the text
		field := strings.TrimSpace(fields[i])
		if !fieldLooksLikePaths(field) {
			break
		}
		paths = append(paths, strings.Split(field, ",")...)
		i++
	}
	text := strings.TrimSpace(strings.Join(fields[i:], " "))
	return paths, text
}

// fieldLooksLikePaths reports whether a tab-separated field is entirely a
// path-block: one or more comma-joined, syntactically valid taxonomy paths.
func fieldLooksLikePaths(field string) bool {
	if field == "" {
		return false
	}
	for _, part := range strings.Split(field, ",") {
		if !validFactPath(strings.ToLower(strings.TrimSpace(part))) {
			return false
		}
	}
	return true
}

// filterFactPathsByTaxonomy keeps only paths whose top-level category exists in
// the taxonomy, recording a warning for each dropped path. Paths are already
// syntactically valid (normalizeFactPaths ran first).
func filterFactPathsByTaxonomy(paths []string, taxonomy factTaxonomy, warnings *[]string) []string {
	tops := factTaxonomyTopLevels(taxonomy)
	kept := paths[:0:0]
	for _, path := range paths {
		if _, ok := tops[factTopLevel(path)]; ok {
			kept = append(kept, path)
			continue
		}
		*warnings = append(*warnings, fmt.Sprintf("dropped path under unknown category: %s", path))
	}
	return kept
}

