import json, sys
# Merge per-repo eval summaries into combined base/expand with repo-namespaced ids.
repos = ["eb", "cli", "eio"]
def load(k, arm):
    return json.load(open(f"/tmp/bench/{k}_{arm}.json"))
for arm in ["base", "expand"]:
    combined = {"results": []}
    for k in repos:
        s = load(k, arm)
        for r in s["results"]:
            r = dict(r)
            r["id"] = f"{k}::{r['id']}"
            combined["results"].append(r)
    json.dump(combined, open(f"/tmp/bench/combined_{arm}.json", "w"))
    print(f"combined_{arm}: {len(combined['results'])} tasks")
PY
echo "pool.py ready"

cd /tmp/bench
python3 <<'PY'
import json, math
base={r['id']:r for k in ['eb','cli','eio'] for r in json.load(open(f'{k}_base.json'))['results']}
# expand summaries keep original ids (no prefix); pair within repo
def rows(arm):
    out={}
    for k in ['eb','cli','eio']:
        for r in json.load(open(f'{k}_{arm}.json'))['results']:
            out[f"{k}::{r['id']}"]=r
    return out
B=rows('base'); E=rows('expand')
from collections import defaultdict
strat=defaultdict(list)
for i in B:
    b,e=B[i],E[i]
    strat[b.get('query_type','?')].append(e['useful_per_1k']-b['useful_per_1k'])
    strat['ALL'].append(e['useful_per_1k']-b['useful_per_1k'])
def tt(d):
    n=len(d); m=sum(d)/n
    if n<2: return m,0,n
    var=sum((x-m)**2 for x in d)/(n-1); sd=math.sqrt(var)
    t=m/(sd/math.sqrt(n)) if sd>0 else 0.0
    coh=m/sd if sd>0 else 0.0
    return m,t,coh,n
print(f"{'stratum':10} {'n':>4} {'mean_d_useful':>14} {'t':>7} {'cohen_d':>8}")
for s in ['ALL','code','concept','howto','convention']:
    if s in strat:
        m,t,coh,n=tt(strat[s]); print(f"{s:10} {n:>4} {m:>14.3f} {t:>7.2f} {coh:>8.2f}")
PY
